// Profiles are mutually isolated portfolios stored in ONE local JSON archive.
// The root contains only the ACTIVE portfolio for backwards compatibility
// with the existing Windows server; inactive portfolios are stored separately.
const PRIMARY_PROFILE_ID='primary';
const PORTFOLIO_FIELDS=['schemaVersion','planPresetVersion','quoteModelVersion','startDate','accounts',
  'investments','marketSettings','plans','movements','customCategories','planOverrides','card','createdAt'];
function safeClone(value){return JSON.parse(JSON.stringify(value));}
function snapshotPortfolio(data){
  const s={};for(const key of PORTFOLIO_FIELDS)if(data[key]!==undefined)s[key]=safeClone(data[key]);
  return s;
}
function ensureProfiles(data){
  if(!Array.isArray(data.profilesMeta)||!data.profilesMeta.length){
    data.profilesMeta=[{id:PRIMARY_PROFILE_ID,name:'Profilo principale'}];
    data.activeProfileId=PRIMARY_PROFILE_ID;
    data.inactiveProfiles={};
  }
  if(!data.profilesMeta.some(p=>p.id===data.activeProfileId))data.activeProfileId=PRIMARY_PROFILE_ID;
  if(!data.inactiveProfiles||typeof data.inactiveProfiles!=='object'||Array.isArray(data.inactiveProfiles))data.inactiveProfiles={};
  return data;
}
function newEmptyPortfolio(){
  const empty=blankState();
  empty.investments=[];
  empty.plans=[];
  empty.planOverrides={};
  empty.movements=[];
  empty.card={openingDebt:0,openingPeriod:monthKey(dNow())};
  empty.accounts=[
    {id:'allianz',name:'Conto corrente principale',group:'personal',observations:[]},
    {id:'tr',name:'Secondo conto',group:'personal',observations:[]},
    {id:'cash',name:'Contanti',group:'personal',observations:[{date:START_DATE,amount:0}]},
    {id:'sella',name:'Conto condiviso (facoltativo)',group:'common',observations:[]}
  ];
  empty.customCategories=[];
  empty.marketSettings={autoRefresh:false};
  return snapshotPortfolio(empty);
}
function currentProfile(){return state.profilesMeta?.find(p=>p.id===state.activeProfileId)||{id:PRIMARY_PROFILE_ID,name:'Profilo principale'};}
function profileName(){return currentProfile().name;}
function saveActiveSnapshot(){
  ensureProfiles(state);
  // Do not keep a second, stale copy of the active portfolio.
  delete state.inactiveProfiles[state.activeProfileId];
}
function changeProfile(id){
  ensureProfiles(state);
  if(id===state.activeProfileId)return;
  const next=state.inactiveProfiles[id];
  if(!next||!state.profilesMeta.some(p=>p.id===id))throw Error('Il profilo non è disponibile: non verrà effettuato alcun cambio.');
  if(quoteInProgress)throw Error('Attendi la fine dell’aggiornamento delle quotazioni prima di cambiare profilo.');
  closeModal();
  state.inactiveProfiles[state.activeProfileId]=snapshotPortfolio(state);
  const incoming=safeClone(next);
  delete state.inactiveProfiles[id];
  for(const key of PORTFOLIO_FIELDS)delete state[key];
  for(const key of PORTFOLIO_FIELDS)if(incoming[key]!==undefined)state[key]=incoming[key];
  state.activeProfileId=id;
  // Pension facts belong ONLY to the original, personal main profile.
  state=normalizeState(state);
  quoteResults={};quoteLastRun=0;
  view='home';movementFilter='all';reportPeriod=monthKey(dNow());
  persist();notify('Profilo selezionato: '+profileName()+'. Premi Salva per salvare il cambio.');
}
function createProfile(){
  if(quoteInProgress)return alert('Attendi il termine dell’aggiornamento delle quotazioni.');
  modal('Nuovo profilo','Nuovo patrimonio indipendente. Non vengono copiati i tuoi saldi o PAC.',
    input('Nome della persona o del profilo','label','text','','maxlength="54" required')+
    '<div class="full insight">Ogni profilo avrà conti, investimenti, movimenti, categorie e storico separati. Tutti restano nell’unico JSON locale: il file va salvato dopo ogni modifica.</div>',
    'Crea profilo',fd=>{
      const label=forField(fd,'label').replace(/\s+/g,' ').trim();
      if(label.length<2||label.length>54)throw Error('Inserisci un nome di 2–54 caratteri.');
      if(state.profilesMeta.some(p=>p.name.toLocaleLowerCase('it')===label.toLocaleLowerCase('it')))throw Error('Nome profilo già utilizzato.');
      const id='profile_'+newId().replace(/[^a-zA-Z0-9]/g,'').slice(-22);
      state.profilesMeta.push({id,name:label});
      state.inactiveProfiles[id]=newEmptyPortfolio();
      persist();closeModal();changeProfile(id);
      return false;
    });
}
function renameProfile(id){
  const p=state.profilesMeta.find(z=>z.id===id);if(!p)return;
  modal('Rinomina profilo','Non cambia i movimenti o i saldi.',
    input('Nome profilo','label','text',p.name,'maxlength="54" required'),'Salva nome',fd=>{
      const label=forField(fd,'label').replace(/\s+/g,' ').trim();
      if(label.length<2||label.length>54)throw Error('Nome di 2–54 caratteri richiesto.');
      if(state.profilesMeta.some(q=>q.id!==id&&q.name.toLocaleLowerCase('it')===label.toLocaleLowerCase('it')))throw Error('Nome già utilizzato.');
      p.name=label;persist();notify('Profilo rinominato. Premi Salva.');
    });
}
function deleteProfile(id){
  if(id===PRIMARY_PROFILE_ID)return alert('Il profilo principale non può essere eliminato. Puoi rinominarlo.');
  const p=state.profilesMeta.find(z=>z.id===id);if(!p)return;
  if(quoteInProgress)return alert('Attendi che termini il recupero delle quotazioni.');
  if(!confirm('Eliminare il profilo «'+p.name+'» e TUTTI i suoi dati? Questa operazione verrà registrata solo premendo Salva.'))return;
  if(!confirm('Ultima conferma: hai già creato un backup JSON?'))return;
  if(state.activeProfileId===id)changeProfile(PRIMARY_PROFILE_ID);
  delete state.inactiveProfiles[id];
  state.profilesMeta=state.profilesMeta.filter(q=>q.id!==id);
  persist();notify('Profilo rimosso in questa sessione. Premi Salva per confermare sul disco.');
}
function addProfileAccount(){
  modal('Aggiungi conto al profilo','Puoi creare conti personali o condivisi indipendenti.',
    input('Nome conto','label','text','','maxlength="70" required')+
    select('Tipo','group',[['personal','Conto personale'],['common','Conto comune (separato dal patrimonio)']],'personal'),
    'Aggiungi conto',fd=>{
      const name=forField(fd,'label').replace(/\s+/g,' ').trim();
      if(name.length<2||name.length>70)throw Error('Nome conto da 2 a 70 caratteri.');
      if(state.accounts.some(a=>a.name.toLowerCase()===name.toLowerCase()))throw Error('Conto già esistente.');
      state.accounts.push({id:'acct_'+newId().replace(/[^A-Za-z0-9]/g,'').slice(-18),name,group:forField(fd,'group')==='common'?'common':'personal',observations:[]});
      persist();notify('Conto aggiunto. Inserisci il primo saldo.');
    });
}
function renameProfileAccount(id){
  const a=state.accounts.find(z=>z.id===id);if(!a)return;
  modal('Rinomina conto','Le operazioni e i saldi collegati non cambiano.',
    input('Nome conto','label','text',a.name,'maxlength="70" required'), 'Salva nome',fd=>{
      const name=forField(fd,'label').trim();
      if(name.length<2||name.length>70)throw Error('Nome da 2 a 70 caratteri.');
      a.name=name;persist();
    });
}
function addProfileInvestment(){
  modal('Aggiungi investimento','In un nuovo profilo parti da zero, senza ereditare PAC e fondi dell’altro profilo.',
    input('Nome investimento','label','text','','maxlength="90" required')+
    select('Tipo','kind',[['etf','ETF / titolo quotato'],['fund','Fondo / PAC'],['pension','Fondo pensione']],'etf')+
    input('Intermediario','provider','text','','maxlength="75" required')+
    input('ISIN (facoltativo)','isin','text','','maxlength="24"')+
    '<div class="full insight">La nuova posizione parte senza capitale o quote. Puoi inserirli dal dettaglio. Le quotazioni non sono collegate automaticamente finché non configuri una fonte affidabile.</div>',
    'Aggiungi investimento',fd=>{
      const name=forField(fd,'label').trim(),provider=forField(fd,'provider').trim();
      if(name.length<2||name.length>90||provider.length<2||provider.length>75)throw Error('Nome e intermediario sono obbligatori.');
      const id='holding_'+newId().replace(/[^A-Za-z0-9]/g,'').slice(-18);
      state.investments.push({id,name,kind:forField(fd,'kind'),provider,isin:forField(fd,'isin').toUpperCase(),ticker:'',pensionLine:'',observations:[],marketQuotes:[],investedBeforeStart:null});
      persist();notify('Investimento aggiunto: ora inserisci la posizione.');
    });
}
