function financialInvestmentRows(items,x,title){
  const rows=items.map(asset=>{
    const z=x.assets[asset.id];
    if(!z)return null;
    let capital=z.invested;
    let capitalKind='Versato dichiarato';
    if(capital===null && z.costBasis!==null){capital=z.costBasis;capitalKind='Costo da quote × prezzo medio (non versamenti)';}
    const validValue=z.value!==null&&Number.isFinite(z.value);
    const gain=validValue&&capital!==null?eurRound(z.value-capital):null;
    const brokerGain=z.brokerVerified&&z.reportedGain!==null?z.reportedGain:null;
    const discrepancy=brokerGain!==null&&gain!==null&&Math.abs(brokerGain-gain)>0.01;
    return {name:asset.name,capital,capitalKind,gain,value:z.value,asOf:z.asOf,broker:z.brokerVerified,
      isETF:asset.kind==='etf'&&asset.provider==='Trade Republic',brokerGain,discrepancy,assetId:asset.id,
      stale:z.quoteStale||z.estimated,publicPrice:z.publicQuotePrice,brokerAsOf:z.brokerAsOf};
  }).filter(Boolean);
  const full=rows.filter(r=>r.capital!==null&&r.value!==null);
  const fullyKnown=full.length===rows.length && rows.length>0;
  const totalInvested=eurRound(full.reduce((n,r)=>n+r.capital,0));
  const totalGain=eurRound(full.reduce((n,r)=>n+r.gain,0));
  const totalValue=eurRound(rows.reduce((n,r)=>n+(r.value||0),0));
  return `<div class="portfolio-table-group"><div class="panel-head"><h2 class="panel-title">${e(title)}</h2><span class="token blue">${rows.length} posizioni</span></div>
    <div class="portfolio-table-wrap"><table class="portfolio-table"><thead><tr><th>Investimento e rilevazione</th><th>Versato / costo</th><th>Plus/minus</th><th>Controvalore</th></tr></thead><tbody>${rows.map(r=>`<tr>
      <td><strong>${e(r.name)}</strong><div class="micro">${r.asOf?'Rilevazione '+fmtDate(r.asOf):'Rilevazione mancante'} · ${r.broker?'Trade Republic verificato':r.stale?'Dato stimato / da verificare':'Dati registrati'}</div>${r.isETF?`<button class="mini-link" data-action="brokervalue" data-id="${e(r.assetId)}">${r.broker?'Aggiorna dato TR':'Allinea Trade Republic'} →</button>`:''}</td>
      <td class="number">${money(r.capital)}<div class="micro">${e(r.capitalKind)}</div></td>
      <td class="number ${r.gain===null?'':valClass(r.gain)}">${r.gain===null?'—':money(r.gain)}${r.discrepancy?`<div class="micro discrepancy">Risultato intermediario: ${money(r.brokerGain)}</div>`:''}</td>
      <td class="number strong">${money(r.value)}</td>
    </tr>`).join('')||'<tr><td colspan="4" class="micro">Nessun investimento in questo profilo: aggiungine uno dalla pagina Investimenti.</td></tr>'}</tbody>
    <tfoot><tr><td>Totale ${e(title)}</td><td class="number">${fullyKnown?money(totalInvested):'Parziale · '+money(totalInvested)}</td><td class="number ${valClass(totalGain)}">${fullyKnown?money(totalGain):'Parziale · '+money(totalGain)}</td><td class="number">${money(totalValue)}</td></tr></tfoot></table></div>
    ${!fullyKnown && rows.length?'<div class="micro lower">Alcuni capitali iniziali non sono stati comunicati. Il totale versato e la relativa plus/minus sono parziali, non stimati a zero.</div>':''}
  </div>`;
}
